<?php foreach ($suppliers as $supplier): ?><tr><td><?= htmlspecialchars($supplier['name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($supplier['contact_name'] ?? '', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($supplier['email'] ?? '', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($supplier['phone'] ?? '', ENT_QUOTES, 'UTF-8') ?></td><td><?= (bool) $supplier['is_active'] ? 'Activo' : 'Inactivo' ?></td><td class="actions"><a href="/SS_NOVA_TECHNOLOGY/public/admin/suppliers/form?id=<?= (int) $supplier['id'] ?>">Editar</a><form method="post" action="/SS_NOVA_TECHNOLOGY/public/admin/suppliers/delete" onsubmit="return confirm('¿Eliminar este proveedor?');"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $supplier['id'] ?>"><button type="submit">Eliminar</button></form><form method="post" action="/SS_NOVA_TECHNOLOGY/public/admin/suppliers/toggle"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $supplier['id'] ?>"><button type="submit"><?= (bool) $supplier['is_active'] ? 'Desactivar' : 'Activar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div>